<!-- wp:artisanpack/accordion {"panelId":"newsletter-faq-4","borderColor":"border-subtle","backgroundColor":"surface","style":{"border":{"width":"3px","style":"solid","radius":"12px"}}} -->
<div class="wp-block-artisanpack-accordion ap-accordion has-border-color has-border-subtle-border-color has-surface-background-color has-background" style="border-style:solid;border-width:3px;border-radius:12px"><!-- wp:artisanpack/accordion-title {"fontSize":"lead","style":{"typography":{"fontWeight":"600","lineHeight":"1.5"}}} -->
<div class="ap-accordion__title"><div class="wp-block-artisanpack-accordion-title ap-accordion__title-content has-lead-font-size" style="font-weight:600;line-height:1.5"><!-- wp:artisanpack/paragraph -->
<p class="wp-block-paragraph">Is this just promotional content?</p>
<!-- /wp:artisanpack/paragraph --></div></div>
<!-- /wp:artisanpack/accordion-title -->

<!-- wp:artisanpack/accordion-body {"textColor":"text-muted","fontSize":"body","style":{"typography":{"lineHeight":"1.65"},"spacing":{"padding":{"top":"0","right":"1.25rem","bottom":"1.125rem","left":"1.25rem"}}}} -->
