<!-- wp:artisanpack/heading {"style":{"typography":{"fontSize":"2rem","fontWeight":"800","letterSpacing":"-0.02em"}}} -->
<h2 class="wp-block-heading" style="font-size:2rem;font-weight:800;letter-spacing:-0.02em">From one developer to another</h2>
<!-- /wp:artisanpack/heading -->

<!-- wp:artisanpack/paragraph {"textColor":"text-muted","style":{"typography":{"fontSize":"1rem","lineHeight":"1.7"}}} -->
<p class="wp-block-paragraph has-text-muted-color has-text-color" style="font-size:1rem;line-height:1.7">The ArtisanPack UI Dispatch is written by Jacob Martella, the creator of ArtisanPack UI. After years of rebuilding the same features across Laravel projects — and watching accessibility get treated as an afterthought — he built an ecosystem of packages to solve both problems.</p>
<!-- /wp:artisanpack/paragraph -->

<!-- wp:artisanpack/paragraph {"textColor":"text-muted","style":{"typography":{"fontSize":"1rem","lineHeight":"1.7"}}} -->
<p class="wp-block-paragraph has-text-muted-color has-text-color" style="font-size:1rem;line-height:1.7">The newsletter shares that journey: what's working, what's not, and practical techniques you can apply to your own projects.</p>
<!-- /wp:artisanpack/paragraph -->

<!-- wp:artisanpack/paragraph {"style":{"typography":{"fontSize":"0.9375rem","fontWeight":"600"},"elements":{"link":{"color":{"text":"var:preset|color|text-link"}}}}} -->
<p class="wp-block-paragraph has-link-color" style="font-size:0.9375rem;font-weight:600"><a href="/about">Learn more about ArtisanPack UI <span data-icon-set="fas" data-icon-name="arrow-right" style="font-size:0.75rem" aria-hidden="true" class="ap-inline-icon"><svg aria-hidden="true" viewBox="0 0 24 24"></svg></span></a></p>
<!-- /wp:artisanpack/paragraph --></div>
